const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem('abayat-'+k))??d}catch{return d}};
let products=read('products',[{id:1,name:'عباية نوف',price:399,stock:12,category:'black',image:'nouf.jpg',desc:'عباية سوداء بتطريز ناعم، تجمع بين البساطة والفخامة. قطعة أنيقة بتفاصيل هادئة ترافقك في كل مناسبة.'},{id:2,name:'عباية ليان',price:489,stock:18,category:'beige',image:'beige.jpg',desc:'درجات البيج الدافئة بقصة مريحة وانسيابية. أناقة ناعمة لإطلالة يومية متكاملة.'},{id:3,name:'عباية سارة',price:420,stock:7,category:'black',image:'nouf.jpg',desc:'تصميم كلاسيكي بلون أسود عميق، وتفاصيل مطرزة بعناية لإطلالة راقية.'},{id:4,name:'عباية جود',price:359,stock:15,category:'beige',image:'beige.jpg',desc:'قصة واسعة ومريحة بألوان طبيعية، تناسب لحظاتك اليومية وتكتمل بذوقك.'}]);
let cart=read('cart',[]),favorites=read('favorites',[]),orders=read('orders',[]),settings=read('settings',{name:'عبايات',phone:'',email:''}),size='M',qty=1,query='',filter='all';
const money=n=>new Intl.NumberFormat('ar-SA').format(n)+' ريال';
const updateCartCount=()=>{$('#count').textContent=cart.reduce((s,x)=>s+x.qty,0)};
const savedData=new Map();
const save=()=>{try{for(const [k,v]of Object.entries({products,cart,favorites,orders,settings})){const value=JSON.stringify(v);if(savedData.get(k)!==value){localStorage.setItem('abayat-'+k,value);savedData.set(k,value)}}updateCartCount();return true}catch(e){toast('تعذر حفظ التغييرات: مساحة المتصفح ممتلئة أو التخزين غير متاح. التغييرات الحالية مؤقتة وقد تُفقد عند إغلاق الصفحة.');return false}};
let pageNumbers={};
function paginate(list,key,limit=24){const pages=Math.max(1,Math.ceil(list.length/limit));const page=Math.min(pages,Math.max(1,pageNumbers[key]||1));pageNumbers[key]=page;return {items:list.slice((page-1)*limit,page*limit),controls:pages>1?`<div class="pagination"><button class="button outline" ${page===1?'disabled':''} onclick="pageNumbers['${key}']=${page-1};render(false)">السابق</button><span>صفحة ${page} من ${pages} · ${list.length} نتيجة</span><button class="button outline" ${page===pages?'disabled':''} onclick="pageNumbers['${key}']=${page+1};render(false)">التالي</button></div>`:''}}

function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function wish(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();render(false)}
function cards(list){return list.map(p=>`<article class="product"><a href="#product/${p.id}" class="product-photo">${mediaImage('product-'+p.id,p.name)}</a><button class="wish" aria-label="إضافة إلى المفضلة" onclick="wish(${p.id})">${favorites.includes(p.id)?'♥':'♡'}</button>${p.id===1?'<span class="badge">الأكثر مبيعًا</span>':''}<a href="#product/${p.id}"><h3>${esc(p.name)}</h3></a><div class="price">${money(p.price)}</div><div class="muted">${productSizes(p).map(esc).join(' · ')}</div></article>`).join('')}
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">تشكيلة خريف ٢٠٢٦</div><h1>أناقة محتشمة<br>لكل تفاصيلك.</h1><p>عبايات بتصاميم عصرية تجمع بين الراحة والفخامة، لتكون كل إطلالة حكاية تشبهك.</p><a href="#shop" class="button">اكتشفي التشكيلة ←</a></div><div class="hero-img">${mediaImage('hero','تشكيلة عبايات')}</div></section><div class="benefits"><div>◇ خامات مختارة<small>تفاصيل تستحق اهتمامك</small></div><div>♧ شحن مجاني<small>للطلبات فوق ٣٠٠ ريال</small></div><div>✓ دفع عند الاستلام<small>تجربة تسوق بكل راحة</small></div><div>♡ أناقة كل يوم<small>تصاميم تناسب تفاصيلك</small></div></div><section class="section"><div class="section-head"><h2>تسوقي حسب ذوقك</h2><a href="#shop">كل التشكيلات ←</a></div><div class="categories">${collectionCards()}</div></section><section class="section"><div class="section-head"><h2>قطع نحبّها، لكِ</h2><a href="#shop">عرض جميع المنتجات ←</a></div><div class="grid">${cards(products.slice(0,8))}</div></section><section class="editorial"><div class="eyebrow">MADE FOR YOUR EVERYDAY</div><h2>الجمال في التفاصيل البسيطة.</h2><p>من أول اختيار، إلى آخر تفصيلة… إطلالتك تبدأ هنا.</p><a href="#shop" class="button outline">تسوقي الآن</a></section>`}
function shop(cat,onlyFav=false){let list=products.filter(p=>(!cat||p.category===cat)&&(!onlyFav||favorites.includes(p.id))&&p.name.includes(query));const paged=paginate(list,'shop');return `<section class="section"><div class="crumb"><a href="#home">الرئيسية</a> / ${onlyFav?'المفضلة':'التشكيلة'}</div><div class="section-head"><h2>${onlyFav?'قطعك المفضلة':'اكتشفي تشكيلتنا'}</h2><span class="muted">${list.length} منتجات</span></div>${!onlyFav?collectionToolbar():''}<div class="grid">${cards(paged.items)}</div>${paged.controls}${!list.length?'<div class="empty">لا توجد منتجات مطابقة.</div>':''}</section>`}
function detail(id){const p=products.find(x=>x.id===+id);if(!p)return '<div class="empty">المنتج غير موجود</div>';const sizes=productSizes(p);if(!sizes.includes(size))size=sizes[0]||'';return `<section class="section"><div class="crumb"><a href="#shop">التشكيلة</a> / ${esc(p.name)}</div><div class="detail">${productGallery(p)}<div><div class="eyebrow">تفاصيل ناعمة، حضور مميز</div><h1>${esc(p.name)}</h1><p>${esc(p.desc)}</p><div class="price">${money(p.price)}</div><p class="muted">${p.stock>0?'متوفر الآن · '+p.stock+' قطعة':'نفدت الكمية'}</p><label>اختاري المقاس</label><div class="sizes">${sizes.map(s=>`<button class="${s===size?'selected':''}" data-size="${esc(s)}" onclick="size=this.dataset.size;render(false)">${esc(s)}</button>`).join('')}</div><label>الكمية</label><div class="qty"><button aria-label="تقليل الكمية" onclick="qty=Math.max(1,qty-1);render(false)">−</button><span>${qty}</span><button aria-label="زيادة الكمية" onclick="qty=Math.max(1,Math.min(${p.stock},qty+1));render(false)">+</button></div><button class="button full" onclick="add(${p.id})" ${p.stock<1?'disabled':''}>إضافة إلى السلة</button><button class="button outline full" onclick="if(add(${p.id}))location.hash='checkout'" ${p.stock<1?'disabled':''}>شراء الآن ←</button><p>الدفع عند الاستلام · الشحن مجاني فوق ٣٠٠ ريال</p><p class="muted">صور ومعلومات توضيحية مستوحاة من المقترح.</p></div></div></section>`}
function add(id){let p=products.find(x=>x.id===id),total=cart.filter(x=>x.id===id).reduce((s,x)=>s+x.qty,0);if(!p||!productSizes(p).includes(size)||!Number.isInteger(qty)||qty<1||total+qty>p.stock){toast('الكمية المطلوبة أكبر من المخزون المتاح');return false}let row=cart.find(x=>x.id===id&&x.size===size);if(row)row.qty+=qty;else cart.push({id,size,qty});save();toast('أُضيفت القطعة إلى سلتك');return true}
const subtotal=()=>cart.reduce((s,x)=>s+products.find(p=>p.id===x.id).price*x.qty,0);
const shipping=()=>subtotal()>=300||!cart.length?0:25;
function changeQty(i,d){const p=products.find(x=>x.id===cart[i].id),other=cart.filter((x,j)=>x.id===p.id&&j!==i).reduce((s,x)=>s+x.qty,0);cart[i].qty=Math.max(1,Math.min(p.stock-other,cart[i].qty+d));save();render(false)}
function summary(){return `<div class="row"><span>قيمة المنتجات</span><b>${money(subtotal())}</b></div><div class="row"><span>التوصيل</span><span>${shipping()?money(shipping()):'مجاني'}</span></div><hr style="border:0;border-top:1px solid #ddd"><div class="row"><strong>الإجمالي</strong><strong>${money(subtotal()+shipping())}</strong></div>`}
function cartPage(){if(!cart.length)return `<div class="empty"><h2>سلتك تنتظر اختياراتك</h2><p>اكتشفي قطعة جديدة تُشبهك.</p><a class="button" href="#shop">تسوقي التشكيلة</a></div>`;return `<section class="section"><h1>سلة التسوق</h1><div class="checkout"><div>${cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-row"><div class="cart-thumb">${mediaImage('product-'+p.id,p.name)}</div><div class="info"><h3>${esc(p.name)}</h3><small>المقاس: ${esc(x.size)}</small><div class="qty"><button onclick="changeQty(${i},-1)">−</button>${x.qty}<button onclick="changeQty(${i},1)">+</button></div></div><div>${money(p.price*x.qty)}<br><button class="remove" onclick="cart.splice(${i},1);save();render(false)">حذف</button></div></div>`}).join('')}</div><aside class="panel"><h2>ملخص الطلب</h2>${summary()}<a class="button full" href="#checkout">متابعة لإتمام الطلب ←</a></aside></div></section>`}
function checkout(){if(!cart.length)return cartPage();return `<section class="section"><div class="crumb"><a href="#cart">السلة</a> / إتمام الطلب</div><h1>خطوة أخيرة… وتكتمل إطلالتك</h1><div class="checkout"><form class="panel" onsubmit="placeOrder(event)"><h2>معلومات التوصيل</h2><div class="demo-note">طلب تجريبي — استخدمي بيانات وهمية للتجربة.</div><label class="field">الاسم الكامل<input name="name" required minlength="3" placeholder="مثال: نوف أحمد"></label><label class="field">رقم الجوال<input name="phone" type="tel" required pattern="[+0-9 ()-]{9,16}" placeholder="05XXXXXXXX" dir="ltr"></label><label class="field">المدينة<select name="city" required><option value="">اختاري المدينة</option><option>الرياض</option><option>جدة</option><option>الدمام</option><option>مكة المكرمة</option><option>المدينة المنورة</option><option>مدينة أخرى</option></select></label><label class="field">العنوان بالتفصيل<textarea name="address" required minlength="5" placeholder="الحي، الشارع، رقم المبنى"></textarea></label><h3>طريقة الدفع</h3><p>◉ الدفع عند الاستلام</p><button class="button full" type="submit">تأكيد الطلب التجريبي</button></form><aside class="panel"><h2>ملخص الطلب</h2>${cart.map(x=>{const p=products.find(p=>p.id===x.id);return `<div class="row"><span>${esc(p.name)} · ${esc(x.size)} × ${x.qty}</span><b>${money(p.price*x.qty)}</b></div>`}).join('')}${summary()}</aside></div></section>`}
function placeOrder(e){e.preventDefault();if(!cart.length)return;for(const item of cart){const product=products.find(p=>p.id===item.id);if(!product||!productSizes(product).includes(item.size)){toast('تغيرت المقاسات المتاحة. احذفي القطعة من السلة واختاري المقاس مجددًا.');return}}for(const p of products){if(cart.filter(x=>x.id===p.id).reduce((s,x)=>s+x.qty,0)>p.stock){toast('تغير المخزون. راجعي السلة');return}}let data=Object.fromEntries(new FormData(e.target));data.name=data.name.trim();data.address=data.address.trim();if(data.name.length<3||data.address.length<5||data.phone.replace(/\D/g,'').length<9){toast('راجعي الاسم ورقم الجوال والعنوان');return}let id='ABY-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);Object.assign(data,typeof orderIdentity==='function'?orderIdentity(data):{});orders.unshift({...data,id,createdAt:Date.now(),total:subtotal()+shipping(),status:'جديد',date:new Date().toLocaleDateString('ar-SA'),items:cart.map(x=>({...x,name:products.find(p=>p.id===x.id).name,price:products.find(p=>p.id===x.id).price}))});for(const x of cart)products.find(p=>p.id===x.id).stock-=x.qty;cart=[];if(typeof rememberGuestOrder==='function')rememberGuestOrder(id);save();location.hash='success/'+id}
function success(id){const o=orders.find(x=>x.id===id);if(!o)return '<div class="empty">الطلب غير موجود</div>';return `<section class="section success"><span class="check">✓</span><h1>تم استلام طلبك التجريبي بنجاح</h1><p>شكرًا لثقتك. دي تجربة توضيحية بدون شحن أو دفع فعلي.</p><div class="steps"><span>١ · مراجعة الطلب</span><span>٢ · التجهيز</span><span>٣ · الشحن والتسليم</span></div><div class="panel"><div class="row"><span>رقم الطلب</span><b dir="ltr">${o.id}</b></div><div class="row"><span>اسم العميل</span><b>${esc(o.name)}</b></div><div class="row"><span>الحالة</span><b>${esc(o.status)}</b></div><div class="row"><span>الإجمالي</span><b>${money(o.total)}</b></div></div><br><a class="button" href="#shop">مواصلة التسوق</a> <a class="button outline" href="#admin/orders">تجربة إدارة الطلب</a></section>`}
const statuses=['جديد','جاري التجهيز','تم الشحن','مكتمل','ملغي'];
function setStatus(id,s){const o=orders.find(x=>x.id===id);if(!o||!statuses.includes(s))return;
const totals=new Map();for(const x of o.items)totals.set(x.id,(totals.get(x.id)||0)+x.qty);
if(o.status==='ملغي'&&s!=='ملغي'){
for(const [pid,n] of totals){const p=products.find(p=>p.id===pid);if(!p||p.stock<n){toast('المخزون لا يكفي لإعادة الطلب');render(false);return}}
for(const [pid,n] of totals)products.find(p=>p.id===pid).stock-=n;
}else if(o.status!=='ملغي'&&s==='ملغي'){for(const [pid,n] of totals){const p=products.find(p=>p.id===pid);if(p)p.stock+=n}}
o.status=s;save();toast('تم تحديث حالة الطلب');render(false)}
function ordersTable(admin=false){const paged=paginate(orders,'customer-orders',20);return orders.length?`<div class="table-wrap"><table><thead><tr><th>الطلب</th><th>العميل</th><th>المدينة</th><th>الإجمالي</th><th>الحالة</th><th>التفاصيل</th></tr></thead><tbody>${paged.items.map(o=>`<tr><td dir="ltr">${o.id}</td><td>${esc(o.name)}</td><td>${esc(o.city)}</td><td>${money(o.total)}</td><td>${admin?`<select aria-label="حالة الطلب" onchange="setStatus('${o.id}',this.value)">${statuses.map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select>`:`<span class="status">${esc(o.status)}</span>`}</td><td><button class="remove" onclick="showOrder('${o.id}')">عرض</button></td></tr>`).join('')}</tbody></table></div>${paged.controls}`:'<div class="empty">لا توجد طلبات بعد. أنشئي طلبًا تجريبيًا من المتجر.</div>'}
function showOrder(id){const o=orders.find(x=>x.id===id);modal(`<h2>تفاصيل الطلب</h2><p dir="ltr">${o.id}</p><p>${esc(o.name)} · ${esc(o.phone)}</p><p>${esc(o.city)} — ${esc(o.address)}</p>${o.items.map(x=>`<div class="row"><span>${esc(x.name)} · ${esc(x.size)} × ${x.qty}</span><b>${money(x.price*x.qty)}</b></div>`).join('')}<hr><p>الإجمالي: ${money(o.total)}</p><p>الدفع عند الاستلام · ${esc(o.status)}</p>`)}
function modal(content){$('#modal')?.remove();const d=document.createElement('dialog');d.id='modal';d.innerHTML=`<button class="remove" style="float:left" onclick="this.closest('dialog').close()">إغلاق ×</button>${content}`;document.body.append(d);d.showModal()}
function admin(tab){let content='';if(tab==='products')content=`<div class="section-head"><h2>المنتجات والمخزون</h2><button class="button" onclick="editProduct()">إضافة منتج +</button></div><div class="table-wrap"><table><tr><th>المنتج</th><th>السعر</th><th>المخزون</th><th>المقاسات</th><th></th></tr>${products.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td>S / M / L / XL / XXL</td><td><button class="remove" onclick="editProduct(${p.id})">تعديل</button></td></tr>`).join('')}</table></div>`;else if(tab==='settings')content=`<h2>إعدادات المتجر</h2><form onsubmit="updateSettings(event)"><label class="field">اسم المتجر<input name="name" value="${esc(settings.name)}" required></label><label class="field">رقم التواصل<input name="phone" value="${esc(settings.phone)}"></label><label class="field">البريد الإلكتروني<input name="email" type="email" value="${esc(settings.email)}"></label><button class="button">حفظ الإعدادات</button></form>`;else content=`<h2>${tab==='orders'?'إدارة الطلبات':'مرحبًا بك في لوحة إدارة المتجر'}</h2><p class="muted">كل تفاصيل متجرك في مكان واحد.</p>${tab!=='orders'?`<div class="stats"><div class="stat">قيمة الطلبات<strong>${money(orders.filter(o=>o.status!=='ملغي').reduce((s,o)=>s+o.total,0))}</strong></div><div class="stat">إجمالي الطلبات<strong>${orders.length}</strong></div><div class="stat">المنتجات<strong>${products.length}</strong></div></div>`:''}${ordersTable(true)}`;return `<section class="admin"><aside class="sidebar"><strong>إدارة عبايات</strong><a href="#admin">◫ الرئيسية</a><a href="#admin/products">◇ المنتجات</a><a href="#admin/orders">▤ الطلبات</a><a href="#admin/settings">⚙ الإعدادات</a><a href="#home">العودة للمتجر ←</a></aside><div><div class="demo-note">لوحة إدارة تجريبية مفتوحة للعرض · البيانات محلية على جهازك.</div><div class="panel" style="margin-top:20px">${content}</div></div></section>`}
function editProduct(id){let p=products.find(x=>x.id===id)||{name:'',price:399,stock:10,category:'black',desc:''};modal(`<h2>${id?'تعديل المنتج':'منتج جديد'}</h2><form onsubmit="saveProduct(event,${id||0})"><label class="field">اسم المنتج<input name="name" required value="${esc(p.name)}"></label><label class="field">السعر بالريال<input name="price" type="number" min="1" required value="${p.price}"></label><label class="field">الكمية المتاحة<input name="stock" type="number" min="0" required value="${p.stock}"></label><label class="field">التشكيلة<select name="category"><option value="black" ${p.category==='black'?'selected':''}>الأسود</option><option value="beige" ${p.category==='beige'?'selected':''}>ألوان هادئة</option></select></label><label class="field">الوصف<textarea name="desc" required>${esc(p.desc)}</textarea></label><button class="button">حفظ المنتج</button></form>`)}
function saveProduct(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim();d.desc=d.desc.trim();d.sizes=[...new Set([...new FormData(e.target).getAll('sizes'),...(d.customSizes||'').split(/[,،]/)].map(s=>s.trim()).filter(Boolean))];delete d.customSizes;if(!d.sizes.length||d.sizes.some(s=>s.length>12)||d.sizes.length>20){toast('اختاري مقاسًا واحدًا على الأقل، بحد أقصى ٢٠ مقاسًا و١٢ حرفًا للمقاس');return}d.price=Number(d.price);d.stock=Number(d.stock);if(!d.name||!d.desc||!Number.isFinite(d.price)||d.price<1||!Number.isInteger(d.stock)||d.stock<0){toast('راجعي اسم المنتج والوصف والسعر والكمية');return}d.image=d.category==='black'?'nouf.jpg':'beige.jpg';if(id)Object.assign(products.find(p=>p.id===id),d);else products.push({...d,id:Date.now()});save();$('#modal').close();render(false);toast('تم حفظ المنتج')}
function updateSettings(e){e.preventDefault();const next=Object.fromEntries(new FormData(e.target));next.name=next.name.trim();next.phone=next.phone.trim();next.email=next.email.trim();if(!next.name){toast('اكتبي اسم المتجر');return}settings=next;save();toast('تم حفظ الإعدادات');render(false)}
function render(scroll=true){let [page,id]=location.hash.slice(1).split('/');document.body.classList.toggle('admin-mode',page==='admin');$('#app').innerHTML=page==='shop'?shop(id):page==='favorites'?shop(null,true):page==='product'?detail(id):page==='cart'?cartPage():page==='checkout'?checkout():page==='success'?success(id):page==='admin'?admin(id):page==='orders'?`<section class="section"><h1>طلباتي</h1>${ordersTable()}</section>`:home();document.querySelectorAll('header .logo,footer .logo').forEach(el=>el.innerHTML=esc(settings.name)+'<small>A B A Y A T</small>');document.title=settings.name+' | أناقة محتشمة لكل تفاصيلك';$('#store-contact').innerHTML=[settings.phone?`<a href="tel:${esc(settings.phone.replace(/[^+0-9]/g,''))}" dir="ltr">${esc(settings.phone)}</a>`:'',settings.email?`<a href="mailto:${esc(settings.email)}">${esc(settings.email)}</a>`:''].join(' ');if(scroll)window.scrollTo(0,0);updateCartCount()}
